import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import * as crypto from 'crypto';

interface CircuitBreakerState {
  failures: number;
  lastFailure: number;
  state: 'closed' | 'open' | 'half-open';
  generation: number;
}

interface SDKConfig {
  serviceName: string;
  region: string;
  failureThreshold: number;
  resetTimeout: number;
  stateDir?: string;
}

class CloudCircuitBreaker {
  private config: SDKConfig;
  private stateFilePath: string;
  private lockFilePath: string;
  private readonly STATE_DIR: string;

  constructor(config: SDKConfig) {
    this.config = config;
    this.STATE_DIR = config.stateDir || path.join(os.tmpdir(), 'cloud-sdk-state-' + crypto.createHash('sha256').update(String(process.getuid?.() ?? process.pid)).digest('hex').substring(0, 8));
    const serviceHash = crypto.createHash('sha256')
      .update(`${config.serviceName}:${config.region}`)
      .digest('hex').substring(0, 16);
    this.stateFilePath = path.join(this.STATE_DIR, `cb-${serviceHash}.state`);
    this.lockFilePath = path.join(this.STATE_DIR, `cb-${serviceHash}.lock`);
    this.ensureStateDirectory();
  }

  private ensureStateDirectory(): void {
    if (!fs.existsSync(this.STATE_DIR)) {
      fs.mkdirSync(this.STATE_DIR, { mode: 0o700, recursive: true });
    } else {
      const dirStats = fs.lstatSync(this.STATE_DIR);
      if (dirStats.isSymbolicLink()) {
        throw new Error('State directory is a symlink - possible attack');
      }
      if (!dirStats.isDirectory()) {
        throw new Error('State path exists but is not a directory');
      }
    }
  }

  private acquireLock(): boolean {
    try {
      const fd = fs.openSync(this.lockFilePath, 'wx');
      fs.writeSync(fd, String(process.pid));
      fs.closeSync(fd);
      return true;
    } catch (e: any) {
      if (e.code === 'EEXIST') {
        const lockStats = fs.lstatSync(this.lockFilePath);
        if (lockStats.isSymbolicLink()) {
          throw new Error('Lock file is a symlink - possible attack');
        }
        const lockAge = Date.now() - lockStats.mtimeMs;
        if (lockAge > 5000) {
          fs.unlinkSync(this.lockFilePath);
          return this.acquireLock();
        }
        return false;
      }
      throw e;
    }
  }

  private releaseLock(): void {
    try {
      fs.unlinkSync(this.lockFilePath);
    } catch (e) {
      // Lock already released
    }
  }

  private readState(): CircuitBreakerState {
    try {
      const fileStats = fs.lstatSync(this.stateFilePath);
      if (fileStats.isSymbolicLink()) {
        throw new Error('State file is a symlink - possible attack');
      }
      const content = fs.readFileSync(this.stateFilePath, 'utf-8');
      return JSON.parse(content) as CircuitBreakerState;
    } catch (e: any) {
      if (e.message?.includes('symlink')) throw e;
      return { failures: 0, lastFailure: 0, state: 'closed', generation: 0 };
    }
  }

  private persistState(state: CircuitBreakerState): void {
    const tempFile = `${this.stateFilePath}.${process.pid}.tmp`;
    const serialized = JSON.stringify(state);
    const fd = fs.openSync(tempFile, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, 0o600);
    fs.writeSync(fd, serialized);
    fs.closeSync(fd);
    fs.renameSync(tempFile, this.stateFilePath);
  }

  public recordFailure(): CircuitBreakerState {
    if (!this.acquireLock()) {
      return this.readState();
    }
    try {
      const state = this.readState();
      state.failures++;
      state.lastFailure = Date.now();
      if (state.failures >= this.config.failureThreshold) {
        state.state = 'open';
      }
      this.persistState(state);
      return state;
    } finally {
      this.releaseLock();
    }
  }

  public recordSuccess(): CircuitBreakerState {
    if (!this.acquireLock()) {
      return this.readState();
    }
    try {
      const state = this.readState();
      state.failures = 0;
      state.state = 'closed';
      state.generation++;
      this.persistState(state);
      return state;
    } finally {
      this.releaseLock();
    }
  }

  public canExecute(): boolean {
    const state = this.readState();
    if (state.state === 'closed') return true;
    if (state.state === 'open') {
      const elapsed = Date.now() - state.lastFailure;
      if (elapsed >= this.config.resetTimeout) {
        return true; // Allow half-open probe
      }
      return false;
    }
    return true;
  }

  public async execute<T>(operation: () => Promise<T>): Promise<T> {
    if (!this.canExecute()) {
      throw new Error(`Circuit breaker open for ${this.config.serviceName}`);
    }
    try {
      const result = await operation();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }

  public getStateFilePath(): string {
    return this.stateFilePath;
  }

  public exportDiagnostics(): object {
    const state = this.readState();
    return { ...state, config: this.config };
  }
}

export { CloudCircuitBreaker, SDKConfig, CircuitBreakerState };
